    def __init__(self, graph):
        self.graph = graph
        self.visited = set()
        self.path = None

    def find_path(self, start, goal):
        if start == goal:
            return [start)  # Direct match in case of start == goal

        if start not in self.graph or goal not in self.graph:
            return None

        self.path = []
        self._find_path_internal(start, goal)

        return self.path

    def _find_path_internal(self, current, goal):
        if current == goal:
            self.path = [current] + self.path
            return True

        self.visited.add(current)
        for neighbor in self.graph[current]:
            if neighbor not in self.visited:
                if self._find_path_internal(neighbor, goal):
                    self.path = [current] + self.path
                    return True
        return False

