        return None
    visited = set()
    path_stack = [(start, [start])]
    while path_stack:
        current_node, path = path_stack.pop()
        if current_node == goal:
            return path
        visited.add(current_node)
        for neighbor in current_node.neighbors:
            if neighbor not in visited:
                new_path = path + [neighbor.id]
                path_stack.append((neighbor, new_path))
    return None
