class Graph:

    def __init__(self, directed=True):
        self.directed = directed
        self.graph = {}

    def add_node(self, node):
        if not self.graph.__contains__(node):
            self.graph[node] = []

    def add_edge(self, start, goal):
        if start in self.graph:
            self.graph[start].append(goal)
        if not self.directed:
            if goal in self.graph:
                self.graph[goal].append(start)

    def find_path(self, start, goal):
        if not self.graph.__contains__(start) or not self.graph.__contains__(goal):
            return None
        visited = set()
        path = []
        path_backtracking = {node: None for node in self.graph}

        def dfs(node):
            if node == goal:
                while node:
                    path.insert(0, node)
                    node = path_backtracking[node]
                return True
            visited.add(node)
            path_backtracking[node] = None
            for neighbor in self.graph[node]:
                if neighbor not in visited:
                    if dfs(neighbor):
                        path_backtracking[node] = neighbor
                        return True
            return False
        dfs(start)
        if path_backtracking[goal] is None:
            return None
        else:
            return path
