class GraphSearch:

    def find_path(self, graph, start, goal):
        path = []
        seen = set()
        path.append(start)
        while path:
            current_node = path.pop()
            if current_node not in seen:
                seen.add(current_node)
                if current_node == goal:
                    return path
                path.extend((n for n in graph.get(current_node, []) if n not in seen))
        return None
